SELECT *
FROM bakery_analysis
WHERE festival LIKE 'No Festival'
LIMIT 10;
SELECT *
FROM bakery_analysis;
-- What is the total revenue generated by each product category?
SELECT product,ROUND(SUM(total_bill),2) AS Revenue
FROM bakery_analysis
GROUP BY product
ORDER BY Revenue DESC;

SELECT product,category,ROUND(SUM(total_bill),2) AS Revenue
FROM bakery_analysis
GROUP BY product,category
ORDER BY Revenue DESC;

-- Which 10 products have the highest total quantity sold?
SELECT product, SUM(quantity) AS total_quantity_sold
FROM bakery_analysis
GROUP BY product
ORDER BY total_quantity_sold DESC
LIMIT 10;

-- Which payment method is used most frequently by customers?
SELECT payment_method,COUNT(payment_method) AS most_frequent_payment_method
FROM bakery_analysis
GROUP BY payment_method
ORDER BY  most_frequent_payment_method DESC;

-- Which season generates the highest total revenue?
SELECT season,ROUND(SUM(total_bill),2) AS total_revenue
FROM bakery_analysis
GROUP BY season
ORDER BY total_revenue DESC;

-- How do sales during festival periods compare with sales during
-- non-festival periods?
SELECT festival, SUM(total_bill) AS Revenue,
(CASE WHEN festival LIKE 'No Festival' THEN 1
ELSE 0
END) AS festival_type
FROM bakery_analysis
GROUP BY festival
;

-- Which days of the week record the highest sales volume?
SELECT day_of_week,SUM(quantity) AS highest_sales_volume
FROM bakery_analysis
GROUP BY day_of_week
ORDER BY highest_sales_volume DESC;

-- Which promotion type generates the highest revenue?
SELECT promotion_type, ROUND(SUM(total_bill),2) AS Revenue
FROM bakery_analysis
GROUP BY promotion_type
ORDER BY Revenue DESC;

-- Which product categories have the highest average discount
-- percentage?
SELECT category,ROUND(AVG(discount_percentage),2) AS avg_discount_percentage
FROM bakery_analysis
GROUP BY category
ORDER BY avg_discount_percentage DESC;

-- Which stores have the highest number of unsold units?
SELECT store_id,SUM(unsold_units) AS old_stock
FROM bakery_analysis
GROUP BY store_id
ORDER BY old_stock DESC;

-- Which products generate the highest gross profit?
SELECT product, ROUND(SUM(total_bill - (cost_price * quantity)),2)AS gross_profit
FROM bakery_analysis
GROUP BY product
ORDER BY gross_profit DESC;

-- Which products generate revenue above the average revenue per
-- product?
SELECT product,SUM(total_bill) AS Revenue
FROM bakery_analysis
GROUP BY product
HAVING  SUM(total_bill)> (
SELECT AVG(product_revenue)  
FROM (
	SELECT  SUM(total_bill) AS product_revenue
	FROM bakery_analysis
	GROUP BY product) AS average_revenue
    )
ORDER BY Revenue DESC;

-- Which stores generate revenue higher than the average revenue
-- across all stores?
SELECT store_id,SUM(total_bill) AS Revenue
FROM bakery_analysis
GROUP BY store_id
HAVING  SUM(total_bill)> (
SELECT AVG(product_revenue)  
FROM (
	SELECT  SUM(total_bill) AS product_revenue
	FROM bakery_analysis
	GROUP BY store_id) AS average_revenue
    )
ORDER BY Revenue DESC;

-- Which product categories have an average discount greater than
-- the overall average discount?
SELECT category, AVG(discount_percentage) AS average_discount
FROM bakery_analysis
GROUP BY category
HAVING AVG(discount_percentage) > ( 
SELECT AVG(discount_percentage) AS overall_average_discount
FROM bakery_analysis
) 
ORDER BY average_discount
;

-- What percentage of total revenue does each season contribute, and
-- which season contributes the most?
WITH total_revenue AS (
SELECT season,SUM(total_bill) as revenue,
SUM(total_bill)*100/(SELECT SUM(total_bill) FROM bakery_analysis) as revenue_percentage
FROM bakery_analysis
GROUP BY season
)

SELECT * 
FROM total_revenue
ORDER BY revenue DESC;

-- Rank stores based on total revenue within each season.

WITH Revenue AS (
SELECT store_id ,ROUND(SUM(total_bill),2) AS total_revenue,season,
RANK() OVER(PARTITION BY season ORDER BY SUM(total_bill) DESC) as revenue_rank
FROM bakery_analysis
GROUP BY store_id,season
)

SELECT * 
FROM Revenue;